import type { Order } from './models/order';

// Newest first. localStorage keeps the list after the browser restarts.
export function recentlyViewedOrders(): Order[] {
  try {
    const stored: unknown = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '[]');
    return Array.isArray(stored) ? stored.filter(isOrder) : [];
  } catch {
    return [];
  }
}

export function rememberViewedOrder(order: Order): void {
  const others = recentlyViewedOrders().filter((viewed) => viewed.id !== order.id);
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify([order, ...others].slice(0, LIMIT)));
  } catch {
    // Full or blocked storage must not stop the order from opening.
  }
}

const STORAGE_KEY = 'orders.recentlyViewed';
const LIMIT = 10;

function isOrder(value: unknown): value is Order {
  return (
    typeof value === 'object' && value !== null &&
    'id' in value && typeof value.id === 'string' &&
    'totalCents' in value && typeof value.totalCents === 'number'
  );
}
EOF
