// Run: bun src/features/orders/recently-viewed.check.ts
import { getOrder, recentlyViewedOrders } from './index';
import { rememberViewedOrder } from './recently-viewed';

const store = new Map<string, string>();
globalThis.localStorage = {
  getItem: (key: string) => store.get(key) ?? null,
  setItem: (key: string, value: string) => store.set(key, value) && undefined,
} as Storage;

function ids(): string {
  return recentlyViewedOrders().map((order) => order.id).join(',');
}

function expect(actual: string, expected: string): void {
  if (actual !== expected) throw new Error(`expected ${expected}, got ${actual}`);
}

for (let id = 1; id <= 12; id++) rememberViewedOrder({ id: String(id), totalCents: 100 });
expect(ids(), '12,11,10,9,8,7,6,5,4,3');

rememberViewedOrder({ id: '5', totalCents: 100 });
expect(ids(), '5,12,11,10,9,8,7,6,4,3');

globalThis.fetch = async () => new Response(JSON.stringify({ id: '42', totalCents: 999 }));
await getOrder('42');
expect(ids(), '42,5,12,11,10,9,8,7,6,4');

store.set('orders.recentlyViewed', '[{"id":"7","totalCents":1},{"id":7},"x"]');
expect(ids(), '7');

store.set('orders.recentlyViewed', 'not json');
expect(ids(), '');

console.log('recently-viewed: ok');
EOF
