import { request } from '../../api/client';
import { formatPrice } from '../../lib/money';
import type { Order } from './models/order';
import { rememberViewedOrder } from './recently-viewed';

export type { Order } from './models/order';
export { recentlyViewedOrders } from './recently-viewed';

export function listOrders(): Promise<Order[]> {
  return request<Order[]>('/orders');
}

export async function getOrder(id: string): Promise<Order> {
  const order = await request<Order>(`/orders/${id}`);
  rememberViewedOrder(order);
  return order;
}

export function orderLabel(order: Order): string {
  return `#${order.id}: ${formatPrice(order.totalCents)}`;
}
